INSERT INTO `brands` (`id`, `name`, `slug`, `country`, `logo_url`, `description`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
  (1, 'Dell', 'dell', 'Mỹ', '/uploads/brands/dell.png', 'Thương hiệu laptop nổi tiếng với dòng XPS, Inspiron, Latitude.', 1, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (2, 'HP', 'hp', 'Mỹ', '/uploads/brands/hp.png', 'Đa dạng từ laptop văn phòng Pavilion, doanh nhân EliteBook đến gaming Victus, Omen.', 2, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (3, 'Asus', 'asus', 'Đài Loan', '/uploads/brands/asus.png', 'Mạnh về laptop gaming ROG/TUF và mỏng nhẹ Zenbook, Vivobook.', 3, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (4, 'Lenovo', 'lenovo', 'Trung Quốc', '/uploads/brands/lenovo.png', 'ThinkPad bền bỉ cho doanh nhân, IdeaPad cho sinh viên, Legion cho game thủ.', 4, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (5, 'Acer', 'acer', 'Đài Loan', '/uploads/brands/acer.png', 'Laptop giá tốt: Aspire, Swift, Nitro, Predator.', 5, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (6, 'Apple', 'apple', 'Mỹ', '/uploads/brands/apple.png', 'MacBook chip Apple Silicon hiệu năng cao, pin trâu.', 6, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (7, 'MSI', 'msi', 'Đài Loan', '/uploads/brands/msi.png', 'Chuyên laptop gaming và sáng tạo nội dung.', 7, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (8, 'LG', 'lg', 'Hàn Quốc', '/uploads/brands/lg.png', 'Dòng LG gram siêu nhẹ, pin lớn.', 8, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (9, 'Microsoft', 'microsoft', 'Mỹ', '/uploads/brands/microsoft.png', 'Dòng Surface Laptop thiết kế tinh tế, màn hình cảm ứng PixelSense.', 9, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49');
