  (1, NULL, 'Laptop văn phòng', 'laptop-van-phong', 'Máy ổn định, pin tốt, phù hợp làm việc hằng ngày.', NULL, 1, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (2, NULL, 'Laptop gaming', 'laptop-gaming', 'Card đồ họa rời, màn hình tần số quét cao, tản nhiệt mạnh.', NULL, 2, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (3, NULL, 'Laptop mỏng nhẹ', 'laptop-mong-nhe', 'Thiết kế gọn nhẹ, dễ mang theo, pin lâu.', NULL, 3, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (4, NULL, 'Laptop đồ họa - kỹ thuật', 'laptop-do-hoa-ky-thuat', 'Màn hình chuẩn màu, cấu hình mạnh cho thiết kế, dựng video.', NULL, 4, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (5, NULL, 'Laptop sinh viên', 'laptop-sinh-vien', 'Giá hợp lý, đủ dùng cho học tập.', NULL, 5, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49'),
  (6, NULL, 'Laptop doanh nhân cao cấp', 'laptop-doanh-nhan', 'Bảo mật, độ bền chuẩn quân đội, thiết kế sang trọng.', NULL, 6, 1, '2026-10-24 01:43:49', '2026-10-24 01:43:49');
INSERT INTO `products` (`id`, `sku`, `barcode`, `name`, `slug`, `brand_id`, `category_id`, `model_name`, `condition_type`, `condition_percent`, `short_description`, `description`, `cost_price`, `price`, `sale_price`, `sale_start`, `sale_end`, `vat_rate`, `stock_quantity`, `low_stock_threshold`, `allow_backorder`, `warehouse_location`, `warranty_months`, `warranty_policy`, `status`, `is_featured`, `is_new`, `is_bestseller`, `sort_order`, `view_count`, `sold_count`, `meta_title`, `meta_description`, `version`, `created_by`, `created_at`, `updated_at`, `deleted_at`) VALUES
  (1, 'DELL-XPS13-9340', '8930000000011', 'Laptop Dell XPS 13 9340 Core Ultra 7 155H 16GB 512GB', 'laptop-dell-xps-13-9340-core-ultra-7-155h-16gb-512gb', 1, 3, 'XPS 13 9340', 'new', 100, 'Siêu mỏng nhẹ 1.19kg, màn hình InfinityEdge 120Hz, chip Intel Core Ultra thế hệ mới.', 'XPS 13 9340 sở hữu thiết kế nhôm nguyên khối cao cấp, bàn phím không viền và touchpad ẩn. Chip Core Ultra 7 tích hợp NPU hỗ trợ tác vụ AI, màn hình 13.4 inch FHD+ 120Hz cho trải nghiệm mượt mà. Phù hợp doanh nhân và người dùng thường xuyên di chuyển.', '37900000', '42990000', '40990000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 4, 5, 0, 'A1-01', 12, 'Bảo hành chính hãng 12 tháng, 1 đổi 1 trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 1, 1, 0, 0, 1536, 53, 'Dell XPS 13 9340 Core Ultra 7 chính hãng giá tốt', 'Mua Dell XPS 13 9340 Core Ultra 7 155H 16GB 512GB chính hãng, bảo hành 12 tháng.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:54:41', NULL),
  (2, 'DELL-INS15-3520', '8930000000028', 'Laptop Dell Inspiron 15 3520 i5-1235U 8GB 512GB', 'laptop-dell-inspiron-15-3520-i5-1235u-8gb-512gb', 1, 5, 'Inspiron 15 3520', 'new', 100, 'Laptop học tập, văn phòng giá tốt, màn hình 15.6 inch 120Hz.', 'Inspiron 15 3520 trang bị Core i5-1235U hiệu năng ổn định cho Word, Excel, duyệt web và học online. Màn hình 120Hz giúp thao tác cuộn trang mượt, bàn phím có numpad tiện nhập liệu.', '12900000', '14990000', '13990000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 25, 8, 0, 'A1-02', 12, 'Bảo hành chính hãng 12 tháng.', 'active', 0, 0, 1, 0, 3425, 122, 'Dell Inspiron 15 3520 i5-1235U giá rẻ', 'Dell Inspiron 15 3520 i5 8GB 512GB phù hợp sinh viên, văn phòng.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:54:06', NULL),
  (3, 'HP-PAV15-EG3', '8930000000035', 'Laptop HP Pavilion 15-eg3 i5-1335U 16GB 512GB', 'laptop-hp-pavilion-15-eg3-i5-1335u-16gb-512gb', 2, 1, 'Pavilion 15-eg3', 'new', 100, 'Văn phòng bền bỉ, RAM 16GB, thiết kế hiện đại.', 'Pavilion 15-eg3 dùng Core i5-1335U thế hệ 13, RAM 16GB đa nhiệm tốt. Màn hình IPS 15.6 inch viền mỏng, loa Bang & Olufsen cho âm thanh sống động khi xem phim.', '15200000', '17490000', '16490000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 22, 5, 0, 'A1-03', 12, 'Bảo hành chính hãng HP 12 tháng.', 'active', 0, 0, 1, 0, 2780, 76, 'HP Pavilion 15-eg3 i5-1335U 16GB', 'HP Pavilion 15 i5-1335U 16GB 512GB chính hãng.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:53:26', NULL),
  (4, 'HP-VICTUS16-R0', '8930000000042', 'Laptop gaming HP Victus 16 Ryzen 5 7640HS 16GB 512GB RTX 4050', 'laptop-gaming-hp-victus-16-ryzen-5-7640hs-16gb-512gb-rtx-4050', 2, 2, 'Victus 16-s0', 'new', 100, 'Gaming tầm trung, RTX 4050, màn hình 16.1 inch 144Hz.', 'Victus 16 kết hợp Ryzen 5 7640HS và RTX 4050 6GB, chơi mượt các tựa game eSports và AAA ở thiết lập trung bình - cao. Tản nhiệt tốt, màn hình 144Hz tràn viền.', '21200000', '23990000', '22990000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 15, 5, 0, 'B2-01', 12, 'Bảo hành chính hãng HP 12 tháng.', 'active', 1, 0, 1, 0, 4110, 64, 'HP Victus 16 RTX 4050 Ryzen 5', 'HP Victus 16 Ryzen 5 7640HS RTX 4050 144Hz giá tốt.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:52:45', NULL),
  (5, 'HP-EB840-G10', '8930000000059', 'Laptop HP EliteBook 840 G10 i7-1355U 16GB 512GB', 'laptop-hp-elitebook-840-g10-i7-1355u-16gb-512gb', 2, 6, 'EliteBook 840 G10', 'new', 100, 'Doanh nhân cao cấp, bảo mật vân tay, chuẩn bền quân đội MIL-STD.', 'EliteBook 840 G10 dành cho doanh nghiệp với vỏ nhôm, bàn phím chống tràn, camera 5MP có màn trập riêng tư và chip bảo mật TPM 2.0. Hiệu năng ổn định với Core i7-1355U.', '34500000', '38990000', NULL, NULL, NULL, '10.00', 8, 3, 0, 'A2-01', 12, 'Bảo hành chính hãng 12 tháng tận nơi cho doanh nghiệp.', 'active', 1, 0, 0, 0, 1260, 21, 'HP EliteBook 840 G10 i7 doanh nhân', 'HP EliteBook 840 G10 i7-1355U 16GB 512GB bảo mật cao.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:51:54', NULL),
  (6, 'ASUS-VB15-X1504', '8930000000066', 'Laptop Asus Vivobook 15 X1504ZA i5-1235U 8GB 512GB', 'laptop-asus-vivobook-15-x1504za-i5-1235u-8gb-512gb', 3, 5, 'Vivobook 15 X1504ZA', 'new', 100, 'Mỏng nhẹ giá rẻ cho sinh viên, bảo hành 24 tháng.', 'Vivobook 15 có thiết kế gọn, màn hình viền mỏng, bàn phím có numpad. Core i5-1235U đáp ứng tốt học tập và làm việc văn phòng.', '11800000', '13490000', '12490000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 40, 10, 0, 'A3-01', 24, 'Bảo hành 24 tháng chính hãng Asus.', 'active', 0, 0, 1, 0, 5230, 158, 'Asus Vivobook 15 X1504ZA i5 giá rẻ', 'Asus Vivobook 15 i5-1235U 8GB 512GB bảo hành 24 tháng.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:51:01', NULL),
  (7, 'ASUS-TUF-F15-FX507', '8930000000073', 'Laptop gaming Asus TUF Gaming F15 FX507ZC4 i7-12700H 16GB 512GB RTX 3050 Ti', 'laptop-gaming-asus-tuf-gaming-f15-fx507zc4-i7-12700h-16gb-512gb-rtx-3050ti', 3, 2, 'TUF Gaming F15 FX507ZC4', 'new', 100, 'Gaming bền bỉ chuẩn quân đội, màn 144Hz, giá hợp lý.', 'TUF Gaming F15 dùng Core i7-12700H 14 nhân mạnh mẽ, card RTX 3050 Ti 4GB. Khung máy đạt chuẩn MIL-STD-810H, tản nhiệt hai quạt cho hiệu năng ổn định khi chơi game lâu.', '21500000', '24490000', '22990000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 18, 5, 0, 'B2-02', 24, 'Bảo hành 24 tháng chính hãng Asus.', 'active', 0, 0, 1, 0, 3893, 97, 'Asus TUF Gaming F15 FX507 i7 RTX 3050 Ti', 'Asus TUF F15 FX507 i7-12700H 16GB RTX 3050 Ti 144Hz.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:50:15', NULL),
  (8, 'ASUS-ROG-G16-G614', '8930000000080', 'Laptop gaming Asus ROG Strix G16 G614JV i9-13980HX 16GB 1TB RTX 4070', 'laptop-gaming-asus-rog-strix-g16-g614jv-i9-13980hx-16gb-1tb-rtx-4070', 3, 2, 'ROG Strix G16 G614JV', 'new', 100, 'Gaming cao cấp, i9 HX, RTX 4070, màn hình QHD+ 240Hz.', 'ROG Strix G16 trang bị Core i9-13980HX 24 nhân và RTX 4070 8GB, màn hình 16 inch QHD+ 240Hz Nebula Display. Hệ thống tản nhiệt kim loại lỏng, đèn RGB Aura Sync, phù hợp game thủ và streamer chuyên nghiệp.', '44500000', '49990000', NULL, NULL, NULL, '10.00', 0, 3, 0, 'B2-03', 24, 'Bảo hành 24 tháng chính hãng Asus, hỗ trợ đổi mới 7 ngày đầu.', 'active', 1, 0, 0, 0, 2950, 29, 'Asus ROG Strix G16 i9 RTX 4070', 'ROG Strix G16 G614JV i9-13980HX RTX 4070 QHD+ 240Hz.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:49:30', NULL),
  (9, 'ASUS-ZB14-UX3405', '8930000000097', 'Laptop Asus Zenbook 14 OLED UX3405MA Core Ultra 7 155H 16GB 1TB', 'laptop-asus-zenbook-14-oled-ux3405ma-core-ultra-7-155h-16gb-1tb', 3, 3, 'Zenbook 14 OLED UX3405MA', 'new', 100, 'Màn hình OLED 2.8K 120Hz, nhẹ 1.2kg, pin 75Wh.', 'Zenbook 14 OLED nổi bật với màn hình 2.8K OLED 120Hz phủ màu DCI-P3 100%, thân máy nhôm Ponder Blue chuẩn quân đội. Core Ultra 7 155H cùng RAM 16GB và SSD 1TB đáp ứng tốt làm việc sáng tạo di động.', '28200000', '31990000', '29990000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 14, 5, 0, 'A3-02', 24, 'Bảo hành 24 tháng chính hãng, tặng kèm túi và chuột không dây.', 'active', 1, 1, 0, 0, 2210, 33, 'Asus Zenbook 14 OLED Core Ultra 7', 'Asus Zenbook 14 OLED UX3405MA Core Ultra 7 155H 16GB 1TB.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:48:44', NULL),
  (10, 'LNV-X1C-G11', '8930000000103', 'Laptop Lenovo ThinkPad X1 Carbon Gen 11 i7-1355U 32GB 1TB', 'laptop-lenovo-thinkpad-x1-carbon-gen-11-i7-1355u-32gb-1tb', 4, 6, 'ThinkPad X1 Carbon Gen 11', 'new', 100, 'Biểu tượng doanh nhân, siêu nhẹ 1.12kg, bàn phím ThinkPad huyền thoại.', 'X1 Carbon Gen 11 sử dụng khung sợi carbon nhẹ, đạt chuẩn MIL-STD-810H. Màn hình WUXGA chống chói, bảo mật vân tay, camera hồng ngoại Windows Hello và pin 57Wh dùng cả ngày.', '47500000', '52990000', NULL, NULL, NULL, '10.00', 5, 3, 0, 'A4-01', 36, 'Bảo hành 36 tháng chính hãng Lenovo Premier Support.', 'active', 1, 0, 0, 0, 1780, 14, 'Lenovo ThinkPad X1 Carbon Gen 11', 'ThinkPad X1 Carbon Gen 11 i7-1355U 32GB 1TB chính hãng.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:48:13', NULL),
  (11, 'LNV-IDP-SLIM3-15', '8930000000110', 'Laptop Lenovo IdeaPad Slim 3 15IAH8 i5-12450H 8GB 512GB', 'laptop-lenovo-ideapad-slim-3-15iah8-i5-12450h-8gb-512gb', 4, 5, 'IdeaPad Slim 3 15IAH8', 'new', 100, 'Cấu hình mạnh trong tầm giá, chip H-series 8 nhân.', 'IdeaPad Slim 3 trang bị Core i5-12450H 8 nhân 12 luồng cho hiệu năng vượt trội so với dòng U cùng tầm giá. Phù hợp sinh viên học đồ họa cơ bản, lập trình và văn phòng.', '12800000', '14490000', '13490000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 35, 8, 0, 'A4-02', 12, 'Bảo hành chính hãng Lenovo 12 tháng.', 'active', 0, 0, 1, 0, 4670, 131, 'Lenovo IdeaPad Slim 3 i5-12450H', 'IdeaPad Slim 3 15IAH8 i5-12450H 8GB 512GB giá tốt.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:47:32', NULL),
  (12, 'LNV-LEGION5-16IRX9', '8930000000127', 'Laptop gaming Lenovo Legion 5 16IRX9 i7-14650HX 16GB 1TB RTX 4060', 'laptop-gaming-lenovo-legion-5-16irx9-i7-14650hx-16gb-1tb-rtx-4060', 4, 2, 'Legion 5 16IRX9', 'new', 100, 'Gaming hiệu năng cao, màn 16 inch WQXGA 165Hz, tản nhiệt Coldfront.', 'Legion 5 16IRX9 mạnh mẽ với Core i7-14650HX 16 nhân và RTX 4060 8GB. Màn hình WQXGA 165Hz sắc nét, bàn phím TrueStrike có đèn RGB 4 vùng, pin 80Wh và sạc 230W.', '35800000', '39990000', '37990000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 3, 5, 0, 'B3-01', 24, 'Bảo hành 24 tháng chính hãng Lenovo.', 'active', 1, 1, 0, 0, 3340, 41, 'Lenovo Legion 5 16IRX9 i7 RTX 4060', 'Legion 5 16IRX9 i7-14650HX 16GB 1TB RTX 4060 WQXGA 165Hz.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 08:46:49', NULL),
