  (76, 'APPL-MBA13M1-1', '8931000000076', 'Laptop Apple MacBook Air 13 inch M1 8GB 256GB', 'laptop-apple-macbook-air-13-inch-m1-8gb-256gb', 6, 3, 'MacBook Air 13 M1 (2020)', 'new', 100, 'Chip M1 bền bỉ, giá dễ tiếp cận, pin lâu. Cấu hình M1/8GB/256GB.', 'MacBook Air M1 vẫn là lựa chọn tốt cho sinh viên và dân văn phòng: không quạt, yên tĩnh, pin dài và hiệu năng vượt trội so với giá. Màn hình Retina 13.3 inch sắc nét, Touch ID tiện lợi. Phiên bản này trang bị Apple M1 (8 nhân, 8 luồng), RAM 8GB Unified Memory, SSD 256GB, card đồ họa Apple M1 GPU 7 nhân, màn hình 13.3 inch 2560x1600 Retina IPS 60Hz.', '17090000', '18990000', '17890000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 14, 8, 0, 'C6-01', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 4924, 34, 'Laptop Apple MacBook Air 13 inch M1 8GB 256GB', 'Mua Laptop Apple MacBook Air 13 inch M1 8GB 256GB chính hãng, bảo hành 12 tháng, giá 18.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 05:10:11', NULL),
  (77, 'APPL-MBA13M3-1', '8931000000077', 'Laptop Apple MacBook Air 13 inch M3 16GB 512GB', 'laptop-apple-macbook-air-13-inch-m3-16gb-512gb', 6, 3, 'MacBook Air 13 M3 (2024)', 'new', 100, 'Chip M3, hỗ trợ 2 màn hình ngoài, pin 18 giờ. Cấu hình M3/16GB/512GB.', 'MacBook Air M3 13 inch có hiệu năng tăng rõ rệt so với M2, hỗ trợ Wi-Fi 6E và xuất hình ra hai màn hình ngoài khi gập máy. Thân máy mỏng 11.3mm, không quạt, pin đến 18 giờ. Phiên bản này trang bị Apple M3 (8 nhân, 8 luồng), RAM 16GB Unified Memory, SSD 512GB, card đồ họa Apple M3 GPU 10 nhân, màn hình 13.6 inch 2560x1664 Liquid Retina IPS 60Hz.', '29690000', '32990000', NULL, NULL, NULL, '10.00', 9, 5, 0, 'C6-02', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 1, 0, 4619, 85, 'Laptop Apple MacBook Air 13 inch M3 16GB 512GB', 'Mua Laptop Apple MacBook Air 13 inch M3 16GB 512GB chính hãng, bảo hành 12 tháng, giá 32.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 05:09:28', NULL),
  (78, 'APPL-MBA13M4-1', '8931000000078', 'Laptop Apple MacBook Air 13 inch M4 16GB 256GB', 'laptop-apple-macbook-air-13-inch-m4-16gb-256gb', 6, 3, 'MacBook Air 13 M4 (2025)', 'new', 100, 'Chip M4, RAM khởi điểm 16GB, camera Center Stage. Cấu hình M4/16GB/256GB.', 'MacBook Air M4 13 inch nâng RAM tiêu chuẩn lên 16GB, camera Center Stage 12MP và hỗ trợ Apple Intelligence. Thiết kế mỏng nhẹ quen thuộc, pin đến 18 giờ và hiệu năng tăng thêm so với M3. Phiên bản này trang bị Apple M4 (10 nhân, 10 luồng), RAM 16GB Unified Memory, SSD 256GB, card đồ họa Apple M4 GPU 8 nhân, màn hình 13.6 inch 2560x1664 Liquid Retina IPS 60Hz.', '24290000', '26990000', NULL, NULL, NULL, '10.00', 15, 5, 0, 'C6-03', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 1, 0, 0, 4356, 29, 'Laptop Apple MacBook Air 13 inch M4 16GB 256GB', 'Mua Laptop Apple MacBook Air 13 inch M4 16GB 256GB chính hãng, bảo hành 12 tháng, giá 26.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 05:05:29', NULL),
  (79, 'APPL-MBA15M2-1', '8931000000079', 'Laptop Apple MacBook Air 15 inch M2 8GB 256GB', 'laptop-apple-macbook-air-15-inch-m2-8gb-256gb', 6, 3, 'MacBook Air 15 M2 (2023)', 'new', 100, 'Màn hình 15.3 inch rộng, loa 6 chiếc, chip M2. Cấu hình M2/8GB/256GB.', 'MacBook Air 15 M2 mang màn hình lớn 15.3 inch trong thân máy mỏng 11.5mm, hệ thống 6 loa và pin 18 giờ. Phù hợp người cần không gian hiển thị lớn nhưng vẫn muốn nhẹ. Phiên bản này trang bị Apple M2 (8 nhân, 8 luồng), RAM 8GB Unified Memory, SSD 256GB, card đồ họa Apple M2 GPU 10 nhân, màn hình 15.3 inch 2880x1864 Liquid Retina IPS 60Hz.', '26990000', '29990000', NULL, NULL, NULL, '10.00', 8, 5, 0, 'C6-04', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 1901, 51, 'Laptop Apple MacBook Air 15 inch M2 8GB 256GB', 'Mua Laptop Apple MacBook Air 15 inch M2 8GB 256GB chính hãng, bảo hành 12 tháng, giá 29.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 05:05:01', NULL),
  (80, 'APPL-MBP14M3-1', '8931000000080', 'Laptop Apple MacBook Pro 14 inch M3 8GB 512GB', 'laptop-apple-macbook-pro-14-inch-m3-8gb-512gb', 6, 4, 'MacBook Pro 14 M3 (2023)', 'new', 100, 'Chip M3, màn hình Liquid Retina XDR, đầy đủ cổng. Cấu hình M3/8GB/512GB.', 'MacBook Pro 14 M3 có màn hình mini-LED XDR 120Hz ProMotion sáng đến 1600 nits (HDR), loa 6 chiếc và đầy đủ HDMI, khe SD. Phù hợp lập trình viên, nhiếp ảnh gia và người sáng tạo nội dung. Phiên bản này trang bị Apple M3 (8 nhân, 8 luồng), RAM 8GB Unified Memory, SSD 512GB, card đồ họa Apple M3 GPU 10 nhân, màn hình 14.2 inch 3024x1964 Liquid Retina XDR (mini-LED) 120Hz.', '35990000', '39990000', NULL, NULL, NULL, '10.00', 7, 5, 0, 'C6-05', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 1742, 67, 'Laptop Apple MacBook Pro 14 inch M3 8GB 512GB', 'Mua Laptop Apple MacBook Pro 14 inch M3 8GB 512GB chính hãng, bảo hành 12 tháng, giá 39.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 05:04:08', NULL),
  (81, 'APPL-MBP14M4-1', '8931000000081', 'Laptop Apple MacBook Pro 14 inch M4 16GB 512GB', 'laptop-apple-macbook-pro-14-inch-m4-16gb-512gb', 6, 4, 'MacBook Pro 14 M4 (2024)', 'new', 100, 'Chip M4, RAM khởi điểm 16GB, 3 cổng Thunderbolt 4. Cấu hình M4/16GB/512GB.', 'MacBook Pro 14 M4 có RAM tiêu chuẩn 16GB, 3 cổng Thunderbolt 4 cùng màn hình XDR sáng đến 1600 nits. Hiệu năng mạnh cho dựng phim, lập trình và thiết kế, pin dùng cả ngày làm việc. Phiên bản này trang bị Apple M4 (10 nhân, 10 luồng), RAM 16GB Unified Memory, SSD 512GB, card đồ họa Apple M4 GPU 10 nhân, màn hình 14.2 inch 3024x1964 Liquid Retina XDR (mini-LED) 120Hz.', '40490000', '44990000', NULL, NULL, NULL, '10.00', 6, 3, 0, 'C6-06', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 1, 0, 0, 2128, 42, 'Laptop Apple MacBook Pro 14 inch M4 16GB 512GB', 'Mua Laptop Apple MacBook Pro 14 inch M4 16GB 512GB chính hãng, bảo hành 12 tháng, giá 44.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 05:02:56', NULL),
  (82, 'APPL-MBP16M3P-1', '8931000000082', 'Laptop Apple MacBook Pro 16 inch M3 Pro 18GB 512GB', 'laptop-apple-macbook-pro-16-inch-m3-pro-18gb-512gb', 6, 4, 'MacBook Pro 16 M3 Pro (2023)', 'new', 100, 'Màn hình 16.2 inch XDR, chip M3 Pro, pin 100Wh. Cấu hình M3 Pro/18GB/512GB.', 'MacBook Pro 16 M3 Pro là máy trạm di động cho editor, nhà thiết kế và lập trình viên với màn hình lớn 16.2 inch XDR, pin 100Wh dùng liên tục nhiều giờ liền và hệ thống tản nhiệt hiệu quả. Phiên bản này trang bị Apple M3 Pro (12 nhân, 12 luồng), RAM 18GB Unified Memory, SSD 512GB, card đồ họa Apple M3 Pro GPU 18 nhân, màn hình 16.2 inch 3456x2234 Liquid Retina XDR (mini-LED) 120Hz.', '60290000', '66990000', NULL, NULL, NULL, '10.00', 3, 3, 0, 'C6-07', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 1, 0, 0, 0, 3205, 7, 'Laptop Apple MacBook Pro 16 inch M3 Pro 18GB 512GB', 'Mua Laptop Apple MacBook Pro 16 inch M3 Pro 18GB 512GB chính hãng, bảo hành 12 tháng, giá 66.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 04:55:23', NULL),
  (83, 'MSI-GF63-1', '8931000000083', 'Laptop gaming MSI Thin GF63 12UC i5-12450H 8GB 512GB RTX 3050', 'laptop-gaming-msi-thin-gf63-12uc-i5-12450h-8gb-512gb-rtx-3050', 7, 2, 'Thin GF63 12UC', 'new', 100, 'Gaming giá rẻ, RTX 3050, thiết kế mỏng. Cấu hình i5-12450H/8GB/512GB.', 'Thin GF63 12UC là laptop gaming giá tốt với Core i5-12450H và RTX 3050, màn hình 144Hz, thân máy mỏng nhẹ so với dòng gaming. Phù hợp game eSports và sinh viên. Phiên bản này trang bị Core i5-12450H (8 nhân, 12 luồng), RAM 8GB DDR4, SSD 512GB, card đồ họa NVIDIA GeForce RTX 3050 4GB, màn hình 15.6 inch 1920x1080 (FHD) IPS 144Hz.', '14950000', '16990000', NULL, NULL, NULL, '10.00', 18, 8, 0, 'B7-01', 24, 'Bảo hành chính hãng 24 tháng. Hỗ trợ tận nơi cho khách hàng doanh nghiệp.', 'active', 0, 0, 1, 0, 5049, 199, 'Laptop gaming MSI Thin GF63 12UC i5-12450H 8GB 512GB RTX ...', 'Mua Laptop gaming MSI Thin GF63 12UC i5-12450H 8GB 512GB RTX 3050 chính hãng, bảo hành 24 tháng, giá 16.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 07:20:23', NULL),
  (84, 'MSI-THIN15-1', '8931000000084', 'Laptop gaming MSI Thin 15 B13UC i5-13420H 16GB 512GB RTX 3050', 'laptop-gaming-msi-thin-15-b13uc-i5-13420h-16gb-512gb-rtx-3050', 7, 2, 'Thin 15 B13UC', 'new', 100, 'Gaming mỏng nhẹ, Core i5 thế hệ 13, RTX 3050. Cấu hình i5-13420H/16GB/512GB.', 'Thin 15 B13UC trang bị Core i5-13420H và RTX 3050, màn hình 144Hz, tản nhiệt Cooler Boost 5. Lựa chọn tốt trong phân khúc gaming phổ thông. Phiên bản này trang bị Core i5-13420H (8 nhân, 12 luồng), RAM 16GB DDR4, SSD 512GB, card đồ họa NVIDIA GeForce RTX 3050 4GB, màn hình 15.6 inch 1920x1080 (FHD) IPS 144Hz.', '16710000', '18990000', NULL, NULL, NULL, '10.00', 14, 8, 0, 'B7-02', 24, 'Bảo hành chính hãng 24 tháng. Hỗ trợ tận nơi cho khách hàng doanh nghiệp.', 'active', 0, 0, 0, 0, 3388, 11, 'Laptop gaming MSI Thin 15 B13UC i5-13420H 16GB 512GB RTX ...', 'Mua Laptop gaming MSI Thin 15 B13UC i5-13420H 16GB 512GB RTX 3050 chính hãng, bảo hành 24 tháng, giá 18.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 04:53:53', NULL),
  (85, 'MSI-CYBORG15-1', '8931000000085', 'Laptop gaming MSI Cyborg 15 A13UDX i7-13620H 16GB 512GB RTX 4050', 'laptop-gaming-msi-cyborg-15-a13udx-i7-13620h-16gb-512gb-rtx-4050', 7, 2, 'Cyborg 15 A13UDX', 'new', 100, 'Gaming thiết kế trong suốt độc đáo, RTX 4050. Cấu hình i7-13620H/16GB/512GB.', 'Cyborg 15 có thiết kế trong suốt phong cách cyberpunk, Core i7-13620H và RTX 4050, màn hình 144Hz. Trọng lượng chỉ ~2kg, dễ mang đi so với laptop gaming thông thường. Phiên bản này trang bị Core i7-13620H (10 nhân, 16 luồng), RAM 16GB DDR5, SSD 512GB, card đồ họa NVIDIA GeForce RTX 4050 6GB, màn hình 15.6 inch 1920x1080 (FHD) IPS 144Hz.', '21990000', '24990000', '23490000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 9, 5, 0, 'B7-03', 24, 'Bảo hành chính hãng 24 tháng. Hỗ trợ tận nơi cho khách hàng doanh nghiệp.', 'active', 0, 0, 0, 0, 1271, 31, 'Laptop gaming MSI Cyborg 15 A13UDX i7-13620H 16GB 512GB R...', 'Mua Laptop gaming MSI Cyborg 15 A13UDX i7-13620H 16GB 512GB RTX 4050 chính hãng, bảo hành 24 tháng, giá 24.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 04:52:01', NULL),
  (86, 'MSI-KATANA17-1', '8931000000086', 'Laptop gaming MSI Katana 17 B13VFK i7-13620H 16GB 1TB RTX 4060', 'laptop-gaming-msi-katana-17-b13vfk-i7-13620h-16gb-1tb-rtx-4060', 7, 2, 'Katana 17 B13VFK', 'new', 100, 'Gaming 17.3 inch, RTX 4060, SSD 1TB. Cấu hình i7-13620H/16GB/1TB.', 'Katana 17 B13VFK có màn hình 17.3 inch FHD 144Hz, Core i7-13620H và RTX 4060 8GB. Tản nhiệt Cooler Boost 5 hiệu quả, bàn phím RGB 4 vùng, SSD 1TB dung lượng lớn. Phiên bản này trang bị Core i7-13620H (10 nhân, 16 luồng), RAM 16GB DDR5, SSD 1TB, card đồ họa NVIDIA GeForce RTX 4060 8GB, màn hình 17.3 inch 1920x1080 (FHD) IPS 144Hz.', '29910000', '33990000', NULL, NULL, NULL, '10.00', 6, 5, 0, 'B7-04', 24, 'Bảo hành chính hãng 24 tháng. Hỗ trợ tận nơi cho khách hàng doanh nghiệp.', 'active', 0, 0, 0, 0, 756, 68, 'Laptop gaming MSI Katana 17 B13VFK i7-13620H 16GB 1TB RTX...', 'Mua Laptop gaming MSI Katana 17 B13VFK i7-13620H 16GB 1TB RTX 4060 chính hãng, bảo hành 24 tháng, giá 33.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 04:50:26', NULL),
  (87, 'MSI-KATANAA15-1', '8931000000087', 'Laptop gaming MSI Katana A15 AI B8VF Ryzen 7 8845HS 16GB 1TB RTX 4060', 'laptop-gaming-msi-katana-a15-ai-b8vf-ryzen-7-8845hs-16gb-1tb-rtx-4060', 7, 2, 'Katana A15 AI B8VF', 'new', 100, 'Gaming Ryzen 7 8845HS có NPU, RTX 4060. Cấu hình Ryzen 7 8845HS/16GB/1TB.', 'Katana A15 AI B8VF dùng Ryzen 7 8845HS tích hợp NPU hỗ trợ AI, RTX 4060 8GB và SSD 1TB, màn hình 15.6 inch 144Hz. Tản nhiệt Cooler Boost 5 và bàn phím RGB 4 vùng. Phiên bản này trang bị Ryzen 7 8845HS (8 nhân, 16 luồng), RAM 16GB DDR5, SSD 1TB, card đồ họa NVIDIA GeForce RTX 4060 8GB, màn hình 15.6 inch 1920x1080 (FHD) IPS 144Hz.', '28150000', '31990000', NULL, NULL, NULL, '10.00', 7, 5, 0, 'B7-05', 24, 'Bảo hành chính hãng 24 tháng. Hỗ trợ tận nơi cho khách hàng doanh nghiệp.', 'active', 0, 1, 0, 0, 1327, 28, 'Laptop gaming MSI Katana A15 AI B8VF Ryzen 7 8845HS 16GB ...', 'Mua Laptop gaming MSI Katana A15 AI B8VF Ryzen 7 8845HS 16GB 1TB RTX 4060 chính hãng, bảo hành 24 tháng, giá 31.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 04:49:28', NULL),
