  (89, 'MSI-PRESTIGE14-1', '8931000000089', 'Laptop MSI Prestige 14 Evo B13M i7-1355U 16GB 1TB', 'laptop-msi-prestige-14-evo-b13m-i7-1355u-16gb-1tb', 7, 3, 'Prestige 14 Evo B13M', 'new', 100, 'Doanh nhân mỏng nhẹ, chuẩn Intel Evo, pin 4 cell. Cấu hình i7-1355U/16GB/1TB.', 'Prestige 14 Evo B13M đạt chuẩn Intel Evo, thân máy 1.3kg, Core i7-1355U, SSD 1TB. Pin dùng cả ngày, bảo mật vân tay, thiết kế tối giản phù hợp doanh nhân. Phiên bản này trang bị Core i7-1355U (10 nhân, 12 luồng), RAM 16GB LPDDR5, SSD 1TB, card đồ họa Intel Iris Xe Graphics, màn hình 14.0 inch 1920x1200 (WUXGA) IPS 60Hz.', '23750000', '26990000', NULL, NULL, NULL, '10.00', 6, 5, 0, 'A7-07', 24, 'Bảo hành chính hãng 24 tháng. Hỗ trợ tận nơi cho khách hàng doanh nghiệp.', 'active', 0, 0, 0, 0, 4429, 24, 'Laptop MSI Prestige 14 Evo B13M i7-1355U 16GB 1TB', 'Mua Laptop MSI Prestige 14 Evo B13M i7-1355U 16GB 1TB chính hãng, bảo hành 24 tháng, giá 26.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 04:42:13', NULL),
