  (92, 'MSI-RAIDER78-1', '8931000000092', 'Laptop gaming MSI Raider GE78HX 13VH i9-13980HX 32GB 2TB RTX 4080', 'laptop-gaming-msi-raider-ge78hx-13vh-i9-13980hx-32gb-2tb-rtx-4080', 7, 2, 'Raider GE78HX 13VH', 'new', 100, 'Flagship gaming 17 inch: i9-13980HX, RTX 4080, QHD+ 240Hz. Cấu hình i9-13980HX/32GB/2TB.', 'Raider GE78HX 13VH là mẫu gaming đầu bảng của MSI với Core i9-13980HX 24 nhân, RTX 4080 12GB, màn hình 17 inch QHD+ 240Hz. Bàn phím SteelSeries RGB từng phím và dải đèn Mystic Light. Phiên bản này trang bị Core i9-13980HX (24 nhân, 32 luồng), RAM 32GB DDR5, SSD 2TB, card đồ họa NVIDIA GeForce RTX 4080 12GB, màn hình 17.3 inch 2560x1440 (QHD) IPS 240Hz.', '87990000', '99990000', NULL, NULL, NULL, '10.00', 1, 3, 0, 'B7-10', 24, 'Bảo hành chính hãng 24 tháng. Hỗ trợ tận nơi cho khách hàng doanh nghiệp.', 'active', 1, 0, 0, 0, 1627, 13, 'Laptop gaming MSI Raider GE78HX 13VH i9-13980HX 32GB 2TB ...', 'Mua Laptop gaming MSI Raider GE78HX 13VH i9-13980HX 32GB 2TB RTX 4080 chính hãng, bảo hành 24 tháng, giá 99.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-27 09:31:18', NULL),
  (93, 'LG-GRAM16-1', '8931000000093', 'Laptop LG gram 16 16Z90S Core Ultra 7 155H 16GB 512GB', 'laptop-lg-gram-16-16z90s-core-ultra-7-155h-16gb-512gb', 8, 3, 'gram 16 16Z90S', 'new', 100, 'Màn hình 16 inch nhưng chỉ nặng 1.2kg, pin 80Wh. Cấu hình Core Ultra 7 155H/16GB/512GB.', 'LG gram 16 là laptop 16 inch siêu nhẹ chỉ khoảng 1.2kg, màn hình WQXGA 16:10 phủ DCI-P3 99%, pin 80Wh. Đạt chuẩn MIL-STD-810H, phù hợp người cần màn hình lớn nhưng vẫn di động. Phiên bản này trang bị Core Ultra 7 155H (16 nhân, 22 luồng), RAM 16GB LPDDR5X, SSD 512GB, card đồ họa Intel Arc Graphics, màn hình 16.0 inch 2560x1600 (WQXGA) IPS 60Hz.', '32550000', '36990000', NULL, NULL, NULL, '10.00', 8, 5, 0, 'A8-01', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 1326, 15, 'Laptop LG gram 16 16Z90S Core Ultra 7 155H 16GB 512GB', 'Mua Laptop LG gram 16 16Z90S Core Ultra 7 155H 16GB 512GB chính hãng, bảo hành 12 tháng, giá 36.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-27 09:28:47', NULL),
  (94, 'LG-GRAM17-1', '8931000000094', 'Laptop LG gram 17 17Z90S Core Ultra 7 155H 16GB 1TB', 'laptop-lg-gram-17-17z90s-core-ultra-7-155h-16gb-1tb', 8, 3, 'gram 17 17Z90S', 'new', 100, 'Màn hình 17 inch rộng rãi, chỉ khoảng 1.35kg. Cấu hình Core Ultra 7 155H/16GB/1TB.', 'LG gram 17 có màn hình 17 inch WQXGA 16:10 phủ DCI-P3 99% nhưng chỉ nặng khoảng 1.35kg, pin 80Wh. Không gian hiển thị lớn cho đa nhiệm, chỉnh sửa tài liệu và xem phim. Phiên bản này trang bị Core Ultra 7 155H (16 nhân, 22 luồng), RAM 16GB LPDDR5X, SSD 1TB, card đồ họa Intel Arc Graphics, màn hình 17.0 inch 2560x1600 (WQXGA) IPS 60Hz.', '35190000', '39990000', NULL, NULL, NULL, '10.00', 5, 5, 0, 'A8-02', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 5167, 5, 'Laptop LG gram 17 17Z90S Core Ultra 7 155H 16GB 1TB', 'Mua Laptop LG gram 17 17Z90S Core Ultra 7 155H 16GB 1TB chính hãng, bảo hành 12 tháng, giá 39.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-27 09:26:41', NULL),
  (95, 'LG-GRAM14-1', '8931000000095', 'Laptop LG gram 14 14Z90S Core Ultra 5 125H 16GB 512GB', 'laptop-lg-gram-14-14z90s-core-ultra-5-125h-16gb-512gb', 8, 3, 'gram 14 14Z90S', 'new', 100, 'Nhẹ chỉ khoảng 1kg, pin 72Wh, chuẩn bền quân đội. Cấu hình Core Ultra 5 125H/16GB/512GB.', 'LG gram 14 chỉ nặng khoảng 999g nhưng vẫn đạt chuẩn MIL-STD-810H. Màn hình WUXGA IPS 14 inch phủ màu DCI-P3 99%, pin 72Wh cho thời gian sử dụng cả ngày. Phiên bản Core Ultra 5 tiết kiệm hơn. Phiên bản này trang bị Core Ultra 5 125H (14 nhân, 18 luồng), RAM 16GB LPDDR5X, SSD 512GB, card đồ họa Intel Arc Graphics, màn hình 14.0 inch 1920x1200 (WUXGA) IPS 60Hz.', '25510000', '28990000', '27290000', '2026-10-24 01:43:49', '2026-11-23 01:43:49', '10.00', 12, 5, 0, 'A8-03', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 5177, 15, 'Laptop LG gram 14 14Z90S Core Ultra 5 125H 16GB 512GB', 'Mua Laptop LG gram 14 14Z90S Core Ultra 5 125H 16GB 512GB chính hãng, bảo hành 12 tháng, giá 28.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-27 09:24:57', NULL),
  (96, 'MICR-SGO3-1', '8931000000096', 'Laptop Microsoft Surface Laptop Go 3 i5-1235U 8GB 256GB', 'laptop-microsoft-surface-laptop-go-3-i5-1235u-8gb-256gb', 9, 5, 'Surface Laptop Go 3', 'new', 100, 'Nhỏ gọn 12.4 inch cảm ứng, vân tay trên phím nguồn. Cấu hình i5-1235U/8GB/256GB.', 'Surface Laptop Go 3 nhỏ gọn 1.13kg, màn hình PixelSense cảm ứng 12.4 inch, bàn phím êm và vân tay tích hợp phím nguồn. Phù hợp học sinh, sinh viên cần máy nhẹ. Phiên bản này trang bị Core i5-1235U (10 nhân, 12 luồng), RAM 8GB LPDDR5, SSD 256GB, card đồ họa Intel Iris Xe Graphics, màn hình 12.4 inch 1536x1024 PixelSense cảm ứng 60Hz.', '15830000', '17990000', NULL, NULL, NULL, '10.00', 12, 8, 0, 'A9-01', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 4887, 25, 'Laptop Microsoft Surface Laptop Go 3 i5-1235U 8GB 256GB', 'Mua Laptop Microsoft Surface Laptop Go 3 i5-1235U 8GB 256GB chính hãng, bảo hành 12 tháng, giá 17.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-27 09:22:50', NULL),
  (97, 'MICR-S5_13-1', '8931000000097', 'Laptop Microsoft Surface Laptop 5 13.5 inch i5-1245U 8GB 256GB', 'laptop-microsoft-surface-laptop-5-13-5-inch-i5-1245u-8gb-256gb', 9, 3, 'Surface Laptop 5 13.5 inch', 'new', 100, 'Thiết kế tinh tế, màn hình PixelSense cảm ứng, bàn phím Alcantara. Cấu hình i5-1245U/8GB/256GB.', 'Surface Laptop 5 13.5 inch có thân nhôm hoàn thiện cao cấp, màn hình PixelSense tỉ lệ 3:2 cảm ứng, bàn phím phủ Alcantara êm ái. Pin dùng cả ngày, hỗ trợ Wi-Fi 6. Phiên bản này trang bị Core i5-1245U (10 nhân, 12 luồng), RAM 8GB LPDDR5x, SSD 256GB, card đồ họa Intel Iris Xe Graphics, màn hình 13.5 inch 2256x1504 PixelSense cảm ứng 60Hz.', '22870000', '25990000', NULL, NULL, NULL, '10.00', 6, 5, 0, 'A9-02', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 4760, 42, 'Laptop Microsoft Surface Laptop 5 13.5 inch i5-1245U 8GB ...', 'Mua Laptop Microsoft Surface Laptop 5 13.5 inch i5-1245U 8GB 256GB chính hãng, bảo hành 12 tháng, giá 25.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-28 23:34:34', NULL),
  (98, 'MICR-S5_15-1', '8931000000098', 'Laptop Microsoft Surface Laptop 5 15 inch i7-1255U 16GB 512GB', 'laptop-microsoft-surface-laptop-5-15-inch-i7-1255u-16gb-512gb', 9, 3, 'Surface Laptop 5 15 inch', 'new', 100, 'Màn hình 15 inch 3:2, Core i7, phù hợp làm việc năng suất. Cấu hình i7-1255U/16GB/512GB.', 'Surface Laptop 5 15 inch có không gian hiển thị 3:2 rộng rãi, cảm ứng, Core i7-1255U và 16GB RAM. Thiết kế thanh lịch, loa Omnisonic, phù hợp công việc văn phòng và sáng tạo nhẹ. Phiên bản này trang bị Core i7-1255U (10 nhân, 12 luồng), RAM 16GB LPDDR5x, SSD 512GB, card đồ họa Intel Iris Xe Graphics, màn hình 15.0 inch 2496x1664 PixelSense cảm ứng 60Hz.', '35190000', '39990000', NULL, NULL, NULL, '10.00', 4, 5, 0, 'A9-03', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 0, 0, 0, 306, 17, 'Laptop Microsoft Surface Laptop 5 15 inch i7-1255U 16GB 5...', 'Mua Laptop Microsoft Surface Laptop 5 15 inch i7-1255U 16GB 512GB chính hãng, bảo hành 12 tháng, giá 39.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-27 09:25:03', NULL),
  (99, 'MICR-S7-1', '8931000000099', 'Laptop Microsoft Surface Laptop 7 13.8 inch Copilot+ PC Snapdragon X Plus X1P-64-100 16GB 512GB', 'laptop-microsoft-surface-laptop-7-13-8-inch-copilot-pc-snapdragon-x-plus-x1p-64-100-16gb-512gb', 9, 3, 'Surface Laptop 7 13.8 inch Copilot+ PC', 'new', 100, 'Snapdragon X Plus, Copilot+ PC, màn hình 120Hz. Cấu hình Snapdragon X Plus X1P-64-100/16GB/512GB.', 'Surface Laptop 7 chạy chip Snapdragon X Plus với NPU 45 TOPS, hỗ trợ đầy đủ tính năng Copilot+ PC. Màn hình PixelSense Flow 120Hz, pin dùng cả ngày. Lưu ý máy chạy Windows 11 trên nền ARM, một số ứng dụng cũ có thể chưa tương thích. Phiên bản này trang bị Snapdragon X Plus X1P-64-100 (10 nhân, 10 luồng), RAM 16GB LPDDR5X, SSD 512GB, card đồ họa Qualcomm Adreno GPU, màn hình 13.8 inch 2304x1536 PixelSense Flow cảm ứng 120Hz.', '29030000', '32990000', NULL, NULL, NULL, '10.00', 10, 5, 0, 'A9-04', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 0, 1, 0, 0, 2603, 5, 'Laptop Microsoft Surface Laptop 7 13.8 inch Copilot+ PC S...', 'Mua Laptop Microsoft Surface Laptop 7 13.8 inch Copilot+ PC Snapdragon X Plus X1P-64-100 16GB 512GB chính hãng, bảo hành 12 tháng, giá 32.990.000 VND.', 2, 1, '2026-10-24 01:43:49', '2026-10-27 10:20:20', NULL),
  (100, 'MICR-SSTUD2-1', '8931000000100', 'Laptop Microsoft Surface Laptop Studio 2 i7-13700H 16GB 512GB RTX 4050', 'laptop-microsoft-surface-laptop-studio-2-i7-13700h-16gb-512gb-rtx-4050', 9, 4, 'Surface Laptop Studio 2', 'new', 100, 'Hybrid laptop - studio - tablet, RTX 4050, 120Hz. Cấu hình i7-13700H/16GB/512GB.', 'Surface Laptop Studio 2 có bản lề độc đáo chuyển đổi laptop, studio và tablet. Core i7-13700H cùng RTX 4050, màn hình PixelSense Flow 120Hz cảm ứng, hỗ trợ Surface Slim Pen 2. Phù hợp designer, nghệ sĩ số. Phiên bản này trang bị Core i7-13700H (14 nhân, 20 luồng), RAM 16GB LPDDR5X, SSD 512GB, card đồ họa NVIDIA GeForce RTX 4050 6GB, màn hình 14.4 inch 2400x1600 PixelSense Flow cảm ứng 120Hz.', '52790000', '59990000', NULL, NULL, NULL, '10.00', 1, 3, 0, 'C9-05', 12, 'Bảo hành chính hãng 12 tháng. Hỗ trợ đổi mới trong 30 ngày nếu lỗi nhà sản xuất.', 'active', 1, 0, 0, 0, 1800, 10, 'Laptop Microsoft Surface Laptop Studio 2 i7-13700H 16GB 5...', 'Mua Laptop Microsoft Surface Laptop Studio 2 i7-13700H 16GB 512GB RTX 4050 chính hãng, bảo hành 12 tháng, giá 59.990.000 VND.', 3, 1, '2026-10-24 01:43:49', '2026-10-27 10:23:46', NULL);
