  (1, 1, 'Nguyễn Văn An', 66, 'Laptop Acer Aspire 5 A515-57 i5-12450H 16GB 512GB', 5, 'Rất hài lòng với sản phẩm', 'Laptop chạy rất mượt, pin trâu đúng như cam kết, đóng gói cẩn thận và giao nhanh.', 'positive', 1, 'Cảm ơn anh An đã tin tưởng Laptop99! Chúc anh làm việc hiệu quả!', 1, '2026-10-24 02:48:54', 'replied', 'customer', '2026-10-24 02:48:54', '2026-10-24 02:48:54'),
  (2, 2, 'Trần Thị Mai', 13, 'Laptop Acer Aspire 5 A515-58P i5-1335U 8GB 512GB', 4, 'Máy đẹp, giá hợp lý', 'Màn hình sắc nét, phím gõ êm. Hài lòng trong tầm giá.', 'positive', 1, NULL, NULL, NULL, 'approved', 'customer', '2026-10-24 02:48:54', '2026-10-24 02:48:54'),
  (3, 3, 'Lê Hoàng Nam', 66, 'Laptop Acer Aspire 5 A515-57 i5-12450H 16GB 512GB', 5, 'Laptop Gaming đỉnh chóp', 'Chiến game AAA mượt mà không bị tụt fps. Tản nhiệt 2 quạt hoạt động rất tốt!', 'positive', 1, 'Cảm ơn Nam đã ủng hộ Laptop99!', 1, '2026-10-24 02:48:54', 'replied', 'customer', '2026-10-24 02:48:54', '2026-10-24 02:48:54'),
