  (7446283, NULL, 'Phan Anh Dũng', 97, 'Laptop Microsoft Surface Laptop 5 13.5 inch i5-1245U 8GB 256GB', 5, 'Đánh giá chân thực', 'Surface Laptop 5 thiết kế nhôm nguyên khối sang xịn, màn hình cảm ứng 3:2 gõ văn bản rất thích.', 'positive', 1, NULL, NULL, NULL, 'approved', 'customer', '2026-10-10 06:48:44', '2026-10-29 06:48:44');
