  (2000012, 'MacBook Chính Hãng VN/A', 'Hiệu Năng Vượt Trội & Pin 18 Giờ', 'Trợ giá thu cũ đổi mới tới 2.500.000đ. Trả góp 0% duyệt 5 phút. Tặng túi chống sốc cao cấp & Chuột không dây.', 'CHÍNH HÃNG APPLE VN/A • BẢO HÀNH 12T', 'blue', 'blue', 'Khám phá ngay', '#/products?brand=Apple', 'MacBook VN/A', 'Ưu đãi sinh viên', '/uploads/banners/banner-1793120237298-b0204139.png', 16, '27990000', '31990000', 'Apple M3 Chip,RAM 16GB Unified,SSD 512GB Siêu Tốc,Màn hình Liquid Retina', 1, 1, 3500, 'full_cover', 'left', 'left center', 'gradient_dark', '2026-10-24 08:04:22', '2026-10-27 09:57:19', 'hero', 'Apple', '[]', NULL, NULL, NULL),
  (2000013, 'Laptop Gaming RTX 40-Series', 'Chiến Mọi Game AAA & Tần Số Quét 165Hz', '', 'GEFORCE RTX 40-SERIES • 165Hz+', 'red', 'indigo', 'Chọn Laptop Gaming', '#/products?cat=2', 'Gaming RTX 40-Series', 'Tặng bộ Gear Gaming', '/uploads/banners/banner-1793120677975-86a57e84.png', 7, '26990000', '30990000', '', 2, 1, 3500, 'full_cover', 'left', 'center center', 'gradient_dark', '2026-10-24 08:04:22', '2026-10-27 10:04:40', 'hero', 'Apple', '[]', NULL, NULL, NULL),
  (2000014, 'Laptop Doanh Nhân & Văn Phòng', 'Mỏng Nhẹ Tinh Tế & Chuẩn Quân Đội', 'Khung nhôm nguyên khối siêu bền, pin cả ngày dài và bảo mật vân tay. Dịch vụ bảo hành tận nơi On-site 24/7.', 'CHUẨN DOANH NHÂN • BẢO HÀNH TẬN NƠI', 'blue', 'emerald', 'Xem Laptop Văn Phòng', '#/products?cat=1', 'Laptop Văn Phòng', 'Bền bỉ, pin trâu', '/uploads/banners/banner-1793120716408-f773ce0e.png', 1, '34990000', '38990000', 'Intel Core Ultra 7,OLED 3K Chuẩn Màu,RAM 32GB,SSD 1TB NVMe', 3, 1, 3500, 'full_cover', 'left', 'center center', 'gradient_dark', '2026-10-24 08:04:22', '2026-10-27 10:05:18', 'hero', 'Apple', '[]', NULL, NULL, NULL),
  (2000016, 'Tuần Lễ MacBook Chính Hãng — Đặc Quyền S-Student Giảm Thêm 1.000.000đ', '', 'Trải nghiệm sức mạnh chip Apple M2 / M3 siêu mượt, thời lượng pin tới 18 giờ. Hỗ trợ Thu cũ lên đời MacBook trợ giá tới 2.500.000đ & Trả góp 0%.', 'CHÍNH HÃNG APPLE VN/A • AUTHORIZED RESELLER', 'blue', 'dark', 'Xem toàn bộ Laptop Apple', '#/products?brand=Apple', 'Apple MacBook', '', '/uploads/banners/banner-1793120337168-408b968e.png', 16, '22990000', '24990000', 'Apple M2,RAM 8GB,SSD 256GB,Retina 13.6"', 1, 1, 3000, 'full_cover', 'left', 'center center', 'gradient_dark', '2026-10-24 08:04:22', '2026-10-27 09:58:59', 'brand_showcase', 'Apple', '["Giảm thêm 500K – 1 Triệu cho HSSV","Thu cũ đổi mới trợ giá 2.5 Triệu","Bảo hành chính hãng Apple VN/A 12 tháng"]', 'Săn Voucher Apple', '#/promos', NULL),
  (2000017, 'Tuần Lễ Laptop ASUS — Sắm Máy Cân Bài, Chiến Game Đỉnh Cao', '', 'Từ dòng Zenbook OLED mỏng nhẹ sang trọng, Vivobook đa nhiệm cho tới chiến thần ROG Strix / TUF Gaming RTX 40-Series tần số quét 144Hz–240Hz.', 'ASUS OFFICIAL CAMPAIGN • TUẦN LỄ ASUS', 'blue', 'indigo', 'Xem toàn bộ Laptop ASUS', '#/products?brand=Asus', 'ASUS / ROG Gaming', '', '/uploads/banners/banner-1793120380819-29b27919.png', 7, '26990000', '30990000', 'Core i7-14650HX,RTX 4060 8GB,RAM 16GB DDR5,SSD 1TB,165Hz', 2, 1, 3000, 'full_cover', 'left', '50% 73%', 'gradient_dark', '2026-10-24 08:04:22', '2026-10-27 10:03:07', 'brand_showcase', 'ASUS', '["Tặng Balo ASUS ROG + Chuột Gaming","Giảm thêm 500K khi thanh toán VNPAY-QR","Bảo hành chính hãng ASUS 24 tháng toàn cầu"]', 'Săn Voucher ASUS', '#/promos', NULL),
  (2000018, 'Đại Tiệc Lenovo AI & Gaming — Tối Ưu Hiệu Năng Cho Đồ Họa & Lập Trình', '', 'Lenovo Legion dẫn đầu hiệu năng gaming kết hợp trí tuệ nhân tạo Lenovo AI Engine+, tản nhiệt Coldfront Hyper thế hệ mới.', 'LENOVO LEGION & THINKPAD • CHÍNH HÃNG', 'blue', 'blue', 'Xem toàn bộ Laptop Lenovo', '#/products?brand=Lenovo', 'Lenovo Legion / AI', '', '/uploads/banners/banner-1793120459666-a8826e7e.png', 10, '29990000', '33990000', 'Ryzen 7 8845H,RTX 4060,RAM 16GB,SSD 1TB,2.5K 165Hz', 3, 1, 3000, 'full_cover', 'left', '50% 75%', 'gradient_dark', '2026-10-24 08:04:22', '2026-10-27 10:03:15', 'brand_showcase', 'Lenovo', '["Tặng Chuột Legion M300 RGB","Trợ giá thu cũ đổi mới 2 Triệu","Bảo hành tận nơi Lenovo Premier Support 36 tháng"]', 'Săn Voucher Lenovo', '#/promos', NULL),
  (2000019, 'Tuần Lễ Laptop Dell — Đỉnh Cao Bền Bỉ, Chuẩn Mực Doanh Nhân', '', 'Dòng Dell Inspiron, Latitude và XPS cao cấp với độ bền chuẩn quân đội, tản nhiệt siêu êm ái và màn hình chống chói bảo vệ mắt.', 'DELL VIETNAM OFFICIAL • BẢO HÀNH TẬN NƠI ON-SITE 24/7', 'blue', 'emerald', 'Xem toàn bộ Laptop Dell', '#/products?brand=Dell', 'Dell ProSupport', '', '/uploads/banners/banner-1793120563445-86d33858.png', 1, '34990000', '38990000', 'Intel Core Ultra 7,OLED 3K,RAM 32GB,SSD 1TB', 4, 1, 3000, 'full_cover', 'left', '50% 74%', 'gradient_dark', '2026-10-24 08:04:22', '2026-10-27 10:02:58', 'brand_showcase', 'Dell', '["Dịch vụ bảo hành tận nơi On-site 24/7","Tặng Balo Dell Pro chính hãng","Gói phần mềm văn phòng bản quyền"]', 'Săn Voucher Dell', '#/promos', NULL),
  (2000020, 'Chiến Binh Rồng Đỏ MSI — Đỉnh Cao Esport & Sáng Tạo Đồ Họa', '', 'Sức mạnh vượt bậc từ dòng MSI Cyborg, Katana và Titan với công nghệ tản nhiệt Cooler Boost độc quyền và phím cơ SteelSeries.', 'MSI TRUE GAMING • HIỆU NĂNG THỐNG TRỊ', 'blue', 'crimson', 'Xem toàn bộ Laptop MSI', '#/products?brand=MSI', 'MSI Gaming Series', '', '/uploads/banners/banner-1793120473519-8a3d0c95.png', 7, '24990000', '27990000', 'Core i7-13620H,RTX 4050,RAM 16GB,SSD 512GB,144Hz', 5, 1, 3000, 'full_cover', 'left', '50% 68%', 'gradient_dark', '2026-10-24 08:04:23', '2026-10-27 10:03:24', 'brand_showcase', 'MSI', '["Tặng Balo MSI Gaming chính hãng","Chuột MSI M99 Gaming","Bảo hành chính hãng 24 tháng"]', 'Săn Voucher MSI', '#/promos', NULL),
  (2000021, 'Tuần Lễ HP — Sự Kết Hợp Hoàn Hảo Giữa Thẩm Mỹ & Sức Mạnh', '', 'Thiết kế nhôm nguyên khối sang trọng cùng âm thanh Bang & Olufsen đỉnh cao, màn hình IPS chống chói và sạc nhanh 50% trong 30 phút.', 'HP OFFICIAL • MỎNG NHẸ TINH TẾ & GAMING', 'blue', 'blue', 'Xem toàn bộ Laptop HP', '#/products?brand=HP', 'HP Pavilion / OMEN', '', '/uploads/banners/banner-1793120547883-2139055c.png', 1, '18990000', '21990000', 'Core i5-1335U,RAM 16GB,SSD 512GB,FHD IPS', 6, 1, 3000, 'full_cover', 'left', '50% 65%', 'gradient_dark', '2026-10-24 08:04:23', '2026-10-27 10:03:32', 'brand_showcase', 'HP', '["Tặng Chuột không dây HP","Túi xách thời trang cao cấp","Bảo hành chính hãng HP 12 tháng"]', 'Săn Voucher HP', '#/promos', NULL),
  (2000022, 'Acer Predator & Swift AI — Bảo Hành VIP 3S1 Nhanh Nhất Việt Nam', '', 'Chính sách bảo hành 3S1: kiểm tra và bảo hành nhanh trong vòng 3 ngày, nếu không xong đổi máy mới tương đương.', 'ACER VIETNAM • BẢO HÀNH VIP 3S1', 'blue', 'indigo', 'Xem toàn bộ Laptop Acer', '#/products?brand=Acer', 'Acer Predator / Swift', '', '/uploads/banners/banner-1793120500601-ce334c84.png', 7, '21490000', '23990000', 'Core i5-13420H,RTX 4050,RAM 16GB,SSD 512GB,144Hz', 7, 1, 3000, 'full_cover', 'left', '50% 71%', 'gradient_dark', '2026-10-24 08:04:23', '2026-10-27 10:03:40', 'brand_showcase', 'Acer', '["Đặc quyền bảo hành VIP 3S1","Tặng Balo Predator Gaming","Hỗ trợ trả góp 0% lãi suất"]', 'Săn Voucher Acer', '#/promos', NULL),
  (2000023, 'Laptop Apple MacBook Air 13 inch M2 8GB 256GB', 'DEAL TÂM ĐIỂM GIỜ VÀNG • TIẾT KIỆM 2.000.000 đ', 'Màn hình Liquid Retina sắc nét, pin trâu 18h, âm thanh 4 loa đỉnh cao.', '🔥 DEAL TÂM ĐIỂM GIỜ VÀNG • TIẾT KIỆM 2.000.000 đ', 'red', 'crimson', 'Mua ngay giá sốc', '#/product/16', '', '', '/uploads/banners/banner-1793120768002-b879a307.png', 16, '22990000', '24990000', 'Apple M2,RAM 8GB Unified Memory,256GB SSD NVMe,Apple M2 GPU 8 nhân,13.6" 2560x1664 60Hz', 1, 1, 3000, 'full_cover', 'left', '43% 50%', 'gradient_dark', '2026-10-24 08:04:23', '2026-10-27 10:06:10', 'hot_deal', 'Apple', '[]', 'Thêm vào giỏ', NULL, NULL),
  (2030001, 'ƯU ĐÃI CỰC SỐC', 'GIẢM TỚI 6 TRIỆU/MÁY', 'SỐ LƯỢNG CÓ HẠN', 'DEAL CỰC SỐC', 'purple', 'purple', 'SĂN DEAL NGAY', '#/product/83', 'Laptop gaming MSI', 'Giá tốt nhất', '/uploads/banners/banner-1793195791702-3aecadba.png', 83, '16990000', '16990000', 'Core i5-12450H,RAM 8GB,SSD 512GB', 1, 1, 3000, 'full_cover', 'left', 'center center', 'gradient_dark', '2026-10-24 11:53:04', '2026-10-28 06:56:36', 'entry_popup', 'Lenovo', '["Chip Core 5 / 7 ĐỜI MỚI","Giá từ 25 TRIỆU","100% sRGB 165Hz"]', 'Xem kho voucher', '#/promos', NULL),
  (2090001, 'Trải Nghiệm Laptop Tương Tác', 'Thế Hệ Mới', 'Xoay góc nhìn 360°, chạm đổi màu kim loại và tùy chọn cấu hình trực quan trong không gian showroom ảo trước khi mua sắm.', '✨ SHOWROOM CÔNG NGHỆ 3D • LAPTOP99', 'red', 'space_gray', 'Khám phá sản phẩm', '#/products', 'Chiến dịch mới', 'Ưu đãi hấp dẫn', '/uploads/banner_macbook_laptop.jpg', NULL, '0', '0', '', 1, 1, 3500, 'background', 'left', 'center center', 'gradient_dark', '2026-10-25 04:52:00', '2026-10-27 08:30:49', 'hero_3d', 'Apple', '["Giảm thêm 500K - 1 Triệu cho HSSV","Thu cũ đổi mới trợ giá 2.5 Triệu","Bảo hành chính hãng 12-24 tháng"]', 'Săn Voucher', '#/promos', NULL),
  (2120001, 'ĐẠI TIỆC LAPTOP CHÍNH HÃNG', 'Ưu đãi cực đỉnh', 'Thiết kế mỏng nhẹ, hiệu năng mạnh mẽ, chính hãng bảo hành uy tín.', '⚡ FLASH SALE GIỜ VÀNG • ĐỘC QUYỀN HÔM NAY', 'red', 'crimson', 'Khám phá ngay', '#/products', 'Chiến dịch mới', 'Ưu đãi hấp dẫn', '/uploads/banners/banner-1793120314141-b04e2f61.png', NULL, '0', '0', '', 1, 1, 3500, 'full_cover', 'left', 'center center', 'gradient_dark', '2026-10-26 03:12:36', '2026-10-27 09:58:36', 'flash_sale', 'Apple', '["Giảm thêm 500K - 1 Triệu cho HSSV","Thu cũ đổi mới trợ giá 2.5 Triệu","Bảo hành chính hãng 12-24 tháng"]', 'Săn Voucher', '#/promos', NULL);
INSERT INTO `news` (`id`, `title`, `slug`, `summary`, `content`, `thumbnail`, `author`, `is_featured`, `status`, `published_at`, `created_at`, `updated_at`) VALUES
  (1, 'Đánh giá MacBook Pro M4: Sức mạnh đồ họa đỉnh cao', 'danh-gia-macbook-pro-m4', 'MacBook Pro trang bị chip M4 Series mang lại hiệu năng đồ họa và thời lượng pin đột phá cho dân lập trình và sáng tạo nội dung.', NULL, '/uploads/news/news-macbook-pro-m4.jpg', 'Chuyên gia Laptop99', 1, 'published', '2026-10-24 01:45:49', '2026-10-24 01:45:49', '2026-10-24 01:45:49'),
  (2, 'Top 5 Laptop Gaming RTX 4060 đáng mua nhất mùa tựu trường 2026', 'top-5-laptop-gaming-rtx-4060-dang-mua-nhat', 'Điểm danh Asus TUF, Lenovo Legion 5, MSI Katana 15 với tản nhiệt buồng hơi và màn hình 165Hz chuẩn thi đấu esports.', NULL, '/uploads/news/news-gaming-rtx4060.jpg', 'Gamer Team', 1, 'published', '2026-10-24 01:45:49', '2026-10-24 01:45:49', '2026-10-24 01:45:49'),
  (3, 'Intel Core Ultra và AMD Ryzen AI: Cuộc đua laptop thế hệ mới', 'intel-core-ultra-vs-amd-ryzen-ai', 'So sánh sức mạnh xử lý NPU chuyên biệt cho tác vụ trí tuệ nhân tạo trên các dòng máy Dell XPS, ThinkPad X1 và HP Envy.', NULL, '/uploads/news/news-intel-ultra-ai.jpg', 'Kỹ thuật viên', 1, 'published', '2026-10-24 01:45:49', '2026-10-24 01:45:49', '2026-10-24 01:45:49');
