  `published_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=30002;


-- ---------------------------------------------------------------------
-- Table: trade_ins
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `trade_ins`;
CREATE TABLE `trade_ins` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(30) NOT NULL,
  `customer_id` int unsigned DEFAULT NULL,
  `customer_name` varchar(100) DEFAULT NULL,
  `customer_phone` varchar(20) DEFAULT NULL,
  `brand` varchar(50) NOT NULL,
  `model` varchar(100) NOT NULL,
  `year` int NOT NULL,
  `ram` int NOT NULL,
  `condition_desc` varchar(255) NOT NULL,
  `estimated_price` decimal(15,0) NOT NULL,
  `final_price` decimal(15,0) DEFAULT NULL,
  `status` enum('Chờ định giá','Đã định giá','Đã chấp nhận','Đã dùng') DEFAULT 'Chờ định giá',
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `used_in_order_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=2000001;


-- ---------------------------------------------------------------------
-- Table: rmas
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `rmas`;
CREATE TABLE `rmas` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(30) NOT NULL,
  `order_id` int unsigned DEFAULT NULL,
  `order_code` varchar(30) NOT NULL,
  `product_id` int unsigned DEFAULT NULL,
  `product_name` varchar(255) DEFAULT NULL,
  `customer_id` int unsigned DEFAULT NULL,
  `type` enum('Đổi','Trả') DEFAULT 'Đổi',
  `reason` text NOT NULL,
  `status` enum('Chờ duyệt','Đã duyệt','Từ chối','Hoàn tất') DEFAULT 'Chờ duyệt',
  `created_at` timestamp DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=2000001;


-- ---------------------------------------------------------------------
-- Table: password_resets
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `password_resets`;
CREATE TABLE `password_resets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `customer_id` int unsigned NOT NULL,
  `identifier` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `otp_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `attempts` tinyint unsigned DEFAULT '0',
  `expires_at` datetime NOT NULL,
  `used_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_identifier` (`identifier`),
  KEY `idx_customer` (`customer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=10274703;


-- ---------------------------------------------------------------------
-- View: v_product_full
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW `v_product_full` AS
SELECT p.id, p.sku, p.name, p.slug, b.name AS brand, c.name AS category,
       p.price, p.sale_price, COALESCE(p.sale_price, p.price) AS final_price,
       p.stock_quantity, p.status, s.cpu_model, s.ram_gb, s.storage_gb, s.gpu_model
FROM products p
JOIN brands b ON b.id = p.brand_id
JOIN categories c ON c.id = p.category_id
LEFT JOIN product_specs s ON s.product_id = p.id;

SET FOREIGN_KEY_CHECKS = 1;
